import os, re, collections, json

root='.'
gofiles=[]
for dp,dn,fn in os.walk(root):
    if any(p in dp for p in ('/node_modules','/.git','/graphify-out','/web')): continue
    for f in fn:
        if f.endswith('.go'): gofiles.append(os.path.join(dp,f))

src={f:open(f,encoding='utf-8',errors='replace').read() for f in gofiles}
pkg={}
for f,s in src.items():
    m=re.search(r'^package\s+(\w+)',s,re.M)
    pkg[f]=m.group(1) if m else '?'

# collect decls under internal/
decl_re=re.compile(r'^func\s+(?:\((\w+)\s+\*?([\w\[\]]+)\)\s+)?([A-Za-z_]\w*)\s*(?:\[[^\]]*\])?\(',re.M)
decls=[]  # (kind, name, recv, pkgname, file, dir)
for f,s in src.items():
    if not f.startswith('./internal/'): continue
    if f.endswith('_test.go'): continue
    for m in decl_re.finditer(s):
        recv=m.group(2); name=m.group(3)
        decls.append((name,recv,pkg[f],f,os.path.dirname(f)))

# import aliases: map file -> {localname: dir}
imp_re=re.compile(r'^\s*(?:(\w+)\s+)?"github.com/usememos/memos/([^"]+)"',re.M)
fileimports={}
for f,s in src.items():
    d={}
    for m in imp_re.finditer(s):
        alias=m.group(1); path='./'+m.group(2)
        d[alias if alias else pkg.get(path+'/dummy','')]=path
        d.setdefault('__paths__',[]).append((alias,path))
    fileimports[f]=d

# directory -> package name
dirpkg={}
for f,p in pkg.items():
    dirpkg.setdefault(os.path.dirname(f),p)

results=[]
for name,recv,pname,dfile,ddir in decls:
    sites=0; callerfuncs=set(); callerfiles=set()
    for f,s in src.items():
        lines=s.split('\n')
        # determine qualifier valid in this file
        quals=set()
        samepkg = (os.path.dirname(f)==ddir)
        if not samepkg:
            for alias,path in fileimports[f].get('__paths__',[]):
                if path==ddir:
                    quals.add(alias if alias else dirpkg.get(path,pname))
        # scan
        cur='<top>'
        for i,l in enumerate(lines):
            dm=re.match(r'^func\s+(?:\([^)]*\)\s*)?([A-Za-z_]\w*)',l)
            if dm: cur=dm.group(1)
            if recv:
                pat=r'\.'+re.escape(name)+r'\s*\('
                hits=len(re.findall(pat,l))
            else:
                hits=0
                if samepkg:
                    hits+=len(re.findall(r'(?<![\w.])'+re.escape(name)+r'\s*\(',l))
                for q in quals:
                    hits+=len(re.findall(r'(?<![\w.])'+re.escape(q)+r'\.'+re.escape(name)+r'\s*\(',l))
            if hits:
                if f==dfile and re.match(r'^func\s',l): continue
                sites+=hits; callerfiles.add(f)
                callerfuncs.add((f,cur))
    results.append((sites,len(callerfuncs),len(callerfiles),name,recv,pname,dfile))

results.sort(reverse=True)
for r in results[:30]:
    print(r)
