        quals=set(local for local,path in fimports[f] if path==ddir)
        if recv:
            if not samedir and not quals: continue
        else:
            if not samedir and not quals: continue
        cur='<top>'
        for i,l in enumerate(s.split('\n')):
            dm=re.match(r'^func\s+(?:\([^)]*\)\s*)?([A-Za-z_]\w*)',l)
            if dm: cur=dm.group(1)
            h=0
            if recv:
                for m in re.finditer(r'(\w*)\s*\.'+re.escape(name)+r'\s*\(',l):
                    if m.group(1) in faliases[f]: continue   # pkg.Func, not a method
                    h+=1
            else:
                if samedir: h+=len(re.findall(r'(?<![\w.])'+re.escape(name)+r'\s*\(',l))
                for q in quals: h+=len(re.findall(r'(?<![\w.])'+re.escape(q)+r'\.'+re.escape(name)+r'\s*\(',l))
            if h:
                if f==dfile and re.match(r'^func\s',l): continue
                tot+=h
                if not f.endswith('_test.go'): totn+=h
                callers.add((f,cur)); files.add(f)
                if len(samples)<4: samples.append(f+':'+str(i+1)+':'+l.strip()[:70])
    rows.append((tot,totn,len(callers),len(files),name,recv,pname,dfile,samples))
rows.sort(reverse=True)
for r in rows[:25]:
